// Build-time configuration. In a compiled binary these values are literals generated by
// scripts/build.ts; nothing here is read from the environment or argv at runtime.

export interface FolderOverrides {
  sent?: string;
  drafts?: string;
  archive?: string;
}

export interface Limits {
  /** Refuse to download a message larger than this (checked via RFC822.SIZE before fetching). */
  maxMessageBytes: number;
  maxAttachments: number;
  maxAttachmentBytes: number;
  /** Plain-text body is truncated to this many characters. */
  maxBodyChars: number;
  /** Draft bodies read from stdin are rejected above this size. */
  maxDraftBytes: number;
  /** list-new returns at most this many headers per call. */
  maxListed: number;
}

export interface BrokerConfig {
  host: string;
  port: number;
  mailbox: string;
  scratchDir: string;
  folderOverrides?: FolderOverrides;
  limits: Limits;
  /** Test-only: extra PEM CA to trust. main.ts / the build script never set this. */
  ca?: string;
}

export const DEFAULT_LIMITS: Limits = {
  maxMessageBytes: 25 * 1024 * 1024,
  maxAttachments: 10,
  maxAttachmentBytes: 10 * 1024 * 1024,
  maxBodyChars: 200_000,
  maxDraftBytes: 256 * 1024,
  maxListed: 200,
};

/** Attachment types the broker will save. Everything else is reported but not written to disk. */
export const ALLOWED_EXTENSIONS: ReadonlySet<string> = new Set([
  "pdf",
  "jpg",
  "jpeg",
  "png",
  "docx",
  "xlsx",
  "txt",
  "csv",
]);
